# -*- coding: utf-8 -*-
import json, os, re, sys
sys.stdout.reconfigure(encoding='utf-8')
ROOT = r'D:/repository'
SEL = r'C:/Users/Administrator/.dsh/cache/memory-audit/select.json'
d = json.load(open(SEL, encoding='utf-8'))

SKIP = {'.git','node_modules','dist','build','.idea','.vscode','coverage','.cache'}
# basename -> list of full paths
index = {}
allpaths = []
for dp, dns, fns in os.walk(ROOT):
    dns[:] = [x for x in dns if x not in SKIP]
    for fn in fns:
        p = os.path.join(dp, fn)
        allpaths.append(p)
        index.setdefault(fn.lower(), []).append(p)

PROJ_MAP = {
 '园区物管2.0':'园区物管2.0','苏住房G':'苏住房G','苏住房C':'苏住房C',
 '苏州市房地产监测V3':'苏州市房地产监测V3','园区公共收益':'园区公共收益',
 '产品2.0':'产品2.0','昆山G':'昆山G','昆山市民':'昆山市民','门户':'门户',
 '泰兴小程序':'泰兴小程序','淮安物管':'淮安物管','苏找房':'苏找房web',
 '苏州房地产监测V3':'苏州市房地产监测V3',
}

def keywords(ct):
    ks = set()
    for m in re.findall(r'`([^`]+)`', ct):
        for t in re.findall(r'[A-Za-z_][A-Za-z0-9_]{5,}|/[A-Za-z][\w/.-]{6,}', m):
            ks.add(t)
    for t in re.findall(r'\b[a-z]+[A-Z][A-Za-z0-9]{5,}\b', ct):
        ks.add(t)
    for t in re.findall(r'\b[A-Z][A-Z0-9_]{6,}\b', ct):
        ks.add(t)
    return [k for k in ks if len(k) >= 7][:14]

for i, c in enumerate(d['candidates'], 1):
    ct = c['content']
    pm = re.search(r'(?:所属项目|Project)\s*[：:]?\s*([^\n；;，,]+)', ct)
    proj = pm.group(1).strip() if pm else ''
    repo_dir = None
    for k, v in PROJ_MAP.items():
        if k in proj:
            repo_dir = os.path.join(ROOT, v); break
    files = re.findall(r'[\w.-]+\.(?:vue|js|ts|jsx|tsx|scss|css|java|sql|json|md|wxss|wxml)', ct)
    files = list(dict.fromkeys(files))
    hits = {}
    for f in files:
        base = os.path.basename(f)
        for p in index.get(base.lower(), []):
            if repo_dir and not p.lower().startswith(repo_dir.lower()):
                continue
            hits.setdefault(base, []).append(p)
    # grep keywords inside hit files
    kws = keywords(ct)
    kw_hits = []
    seen = set()
    for base, paths in hits.items():
        for p in paths[:2]:
            if p in seen: continue
            seen.add(p)
            try:
                txt = open(p, encoding='utf-8', errors='ignore').read()
            except Exception:
                continue
            for kw in kws:
                if kw in txt:
                    kw_hits.append((os.path.relpath(p, ROOT), kw))
    print(f'=== {i:02d} | {c["body_sha256_16"]} | {c["uri"].split("/")[-1]}')
    print(f'    PROJ={proj} REPO={"YES:"+os.path.basename(repo_dir) if repo_dir and os.path.isdir(repo_dir) else "NO/NONE"}')
    print(f'    FILES={len(hits)}/{len(files)} hit={" ".join(list(hits)[:8])}')
    if kw_hits:
        for p, kw in kw_hits[:10]:
            print(f'    KW  {kw} @ {p}')
    else:
        print(f'    KW  NONE')

