def key_tokens(ct):
    toks = set()
    for m in re.findall(r'`([^`]+)`', ct):
        m=m.strip()
        toks.add(m)
    for t in re.findall(r'\b[a-z][a-zA-Z0-9]{6,}\b', ct):
        if t not in STOP: toks.add(t)
